UPDATE recipes SET steps='["鱼片分别放入密封袋，鱼皮向下放在盘子中。", "取葱白切丝 25g，姜去皮后切丝，10g，混合在一起后分成两半，分别放在袋内鱼片上。", "每个袋子倒入 2.5mL 料酒。", "封好密封袋，放入微波炉中，中火（800 瓦）微波至不透明且容易散开时（约 3.5-5 分钟），从袋中取出鱼片。", "去除青葱和姜。", "取酱油 25mL，芝麻油 2mL，混合均匀后平均淋在两片鱼片上。", "取葱绿切细丝 10g，姜去皮后切丝 3g，混合后分成两份撒在鱼片上。", "取花生油 50mL，在小锅中加热至 190℃。", "将热油淋到放油葱绿的鱼片上，立刻上桌。"]' WHERE id=572;
UPDATE recipes SET steps='["葱、姜、蒜、干辣椒分别清洗干净。", "葱白处切段，每段长度约 4cm，再将每段劈为四瓣。", "姜切片，每片厚度约 3mm。", "一个大蒜拍碎切末，其余蒜切为二瓣。", "干辣椒切四段。", "五花肉切片，约 4cm×4cm。", "清洗鱼。", "鱼背肉厚处拉几道斜口，方便入味", "锅里多倒点油，烧至 7 成热（刚刚开始冒烟），下入鱼炸 1 分钟至鱼皮稍稍变硬捞出备用（注意不要一下锅就拨弄鱼，等炸一会再拨弄、翻面），炸鱼的油倒出，锅里留一点底油", "将锅里底油烧热，下入五花肉，煸出香味。", "放入干辣椒、葱、姜、蒜瓣，翻炒 1 分钟。", "将炸好的鱼倒入锅中。", "沿锅边倒入", "调至中火，将水烧开。", "调至小火，慢焖入味。", "15 分钟 后，打开锅盖，挑出锅里的葱、姜、蒜、干辣椒。", "调至大火收汁，汤汁剩余 1/4 时，撒点蒜末，关火盛出。", "红烧鲤鱼出锅！"]' WHERE id=577;
UPDATE recipes SET description='香叶八角桂皮爆香，郫县豆瓣炒出红油，整罐啤酒焖透，虾肉又麻又鲜' WHERE id=580;
UPDATE recipes SET description='红虾单面贴着平底锅煎到壳边微焦，淋一圈白葡萄酒收一下，挤柠檬汁上桌' WHERE id=581;
UPDATE recipes SET steps='["剪虾枪到根上，虾须虾爪都剪掉，沙包挑掉，开背虾线挑出来，洗净备用", "炸料油", "下油，虾摆放整齐，两面变色后轻轻摁虾头", "大火烧开转小火盖盖子闷（中途不能再加汤水，不要开盖）", "皮亮虾弯就可以起锅，虾摆盘", "收汁（过滤后倒回锅里收浓，放葱油 ） 汤汁剩余 1/4 时。", "浇汁", "完成", "开吃✅"]' WHERE id=582;
UPDATE recipes SET steps='["姜切片切丝、香葱的葱白切段，葱绿切丝，切丝后放入冷水浸泡备用。", "鲈鱼处理好后洗净，用厨房纸擦干，两面分别划几刀，用盐洗掉鱼身的粘液，并用 10g 盐抹遍鱼身的内外，腌制 10 分钟以上。", "补充一个鲈鱼改刀和摆盘的方法，改刀后可以让鲈鱼立起来蒸，均匀受热，同时吃起来更加方便，无需翻面。", "鱼肚内塞上姜和葱白，鱼身也撒上姜和葱白，量为备用的一半。蒸鱼的碟子用筷子将鱼跟碟子隔开蒸", "水烧热感觉到水温后放进入鱼", "大火清蒸 10 分钟。", "蒸好的鱼，用干净的盘子装起来并去除身上姜蒜", "鱼身浇上 15ml 蒸鱼豉油", "鱼身重新撒上姜和葱丝，锅内加上 10ml 食用油并烧热，将食用油淋至鱼身即可出菜"]' WHERE id=584;
UPDATE recipes SET steps='["将鱼清洗干净，确保无鱼鳞等异物", "将鱼头朝左，鱼肚朝下，右手持刀。刀竖直切下 1cm，按紧鱼身往左片 3-4cm，再将鱼片中间轻轻划一刀", "将鱼放进盆里，然后将大姜切片，大葱切段（随便切切就行了，主要是需要去腥味）", "用吃奶的力气将大葱大姜里的汁水挤到盆中", "加入 20g 盐，25g 料酒，然后给鲤鱼搓个澡，涂抹均匀", "找个干净的盆，加入 100g 面粉、200g 淀粉、180g 水、5g 盐，用手将其搅拌均匀，面糊此时粘稠呈可拉丝状态，然后打入一个鸡蛋，再次搅匀", "等待 30 分钟", "将鱼放在案板上，用干毛巾将鱼身上的水擦干（这样可以更好的挂糊）", "将盆冲洗干净，用干毛巾擦干", "起锅烧油，加入约 1L 的油，将油温烧至 7 成热，约 200-240 度", "捏起鱼的尾巴，将鱼头沉入锅底，用勺子往鱼的身上淋热油，待面糊成型后，将鱼慢慢放入锅中，拿锅铲轻轻铲起鱼的头部，然后垫上笊篱。防止底部炸糊。", "准备一个盛鱼的盘子，放在锅的旁边。", "用锅铲从鱼身处轻轻铲入，两个工具配合鱼翻个身。再炸两分钟，还是同样的方式（笊篱托着鱼头，锅铲托着鱼身，将鱼盛入盘中）", "将锅中的油倒入擦干的盆中，放置一边，然后将锅刷干净", "将 50g 清水、40g 番茄酱、20g 白糖、10g 白醋放入小碗中，搅拌均匀", "再准备一个小碗加入 10g 淀粉、10g 水，搅拌成水淀粉", "开大火将锅烧热，然后倒入之前准备的料汁，大火烧开，转小火", "加入调好的水淀粉，边倒边搅拌，然后 20 秒后关火", "将熬好的糖醋汁用勺子均匀地浇在鱼身上，可以加点香菜或葱花点缀，糖醋鲤鱼就做好了"]' WHERE id=586;
UPDATE recipes SET description='罗氏虾开背煎到壳脆，黄油裹住蒜蓉香，芥末的辛劲在后面追上来' WHERE id=587;
UPDATE recipes SET description='葱白先煎出甜香，再和蚝油汁一起喂给海参，勾芡到汤汁能挂勺', steps='["葱白切成 1cm 的段，备用。", "海参切成 1cm 的段，备用。", "准备一个空碗，倒入 20g 蚝油， 10g 生抽， 2g 白糖，搅拌均匀。", "另一个空碗倒入淀粉，水，制备水淀粉，勾芡用。", "热锅，锅内放入 20ml - 25ml 食用油。等待 10 秒让油温升高。", "放入葱白，调小火，注意不要让葱白变焦。大概煎 3-5 分钟即可。", "用筷子夹出葱白，放入盘中备用。", "倒入调好的料汁，炒香，等待 1 - 2 分钟 。", "放入切好的海参，翻炒 1 分钟", "加入 100 ml 的水， 中小火， 等待 5 分钟", "等待锅中汤汁快干的时候，加入水淀粉，加入前面取出的葱白", "在外观呈粘稠状态后关火，盛盘"]', ingredients='["泡发好的海参", "大葱葱白"]' WHERE id=589;
