UPDATE recipes SET steps='["将生姜拍碎（不用切太碎，拍开即可释放姜汁）", "将小豆蔻用刀背拍开，露出里面的籽", "将黑胡椒粒拍碎", "在小奶锅中倒入 120ml 水", "放入拍碎的生姜、小豆蔻、肉桂棒、丁香、黑胡椒粒", "大火煮沸后转小火，煮 2 分钟，让香料的味道充分释出", "加入红茶 8g，继续小火煮 2 分钟，直至茶汤颜色变深", "倒入全脂牛奶 120ml", "中火加热，注意观察，当奶茶开始冒泡上升时立即转小火（牛奶极易溢出）", "小火煮 2-3 分钟，期间可以将锅提起倒回（反复提拉 3-4 次），使茶汤与牛奶充分融合", "加入糖，搅拌溶解", "关火", "用滤网过滤到茶盏中，去除茶叶和香料残渣", "趁热饮用"]' WHERE id=654;
