UPDATE recipes SET steps='["蒜苔切成 5cm 小段，备用", "五花肉切成 5mm × 5cm 丝状，备用", "蒜瓣拍碎切成末，备用", "热锅，锅内放入 10ml 食用油。等待 10 秒让油温升高", "放入蒜末，中火翻炒 10 秒 将蒜末炒出香味", "放入五花肉和 5ml 生抽，中火翻炒 30 秒 将肉炒熟并上色", "将蒜苔放入锅内并加入 10ml 生抽，翻炒 30 秒", "锅内加入 20g 水，中火翻炒 5 分钟 将蒜苔炒至稍稍变软", "最后加入 2g 食盐，中火翻炒 30 秒，即可出锅装盘"]' WHERE id=704;
UPDATE recipes SET steps='["在大碗中混合酸奶、生姜泥、大蒜泥、红辣椒粉、姜黄粉、盐、柠檬汁", "放入鸡肉块，充分裹上腌料", "盖保鲜膜，冷藏腌制至少 1 小时", "在平底锅中倒入 15ml 食用油，大火加热", "将腌好的鸡肉块放入锅中（不要倒入腌料汁）", "大火煎至两面焦黄（每面约 3 分钟），鸡肉不需要完全煮熟", "盛出备用", "在锅中放入番茄块、洋葱块、腰果、生姜、大蒜和水 100ml", "大火煮沸后转中火，煮 15 分钟，直至所有材料完全软烂", "稍微冷却后，倒入搅拌机中打成细腻顺滑的泥状", "用滤网过滤一遍，去除渣滓，得到顺滑的酱汁，备用", "在炒锅中放入黄油 50g，中火加热融化", "倒入过滤好的番茄酱汁", "加入红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 5g", "翻炒 3-5 分钟，直至酱汁颜色变深且油花浮出", "放入烤好的鸡肉块，翻拌均匀", "加入糖 10g（平衡番茄的酸味），搅拌", "倒入淡奶油 100ml，搅拌均匀", "小火炖 10-12 分钟，使鸡肉完全熟透且吸收酱汁", "加入印度综合香料粉 3g、小豆蔻粉 2g", "撒入干葫芦巴叶 3g（用手搓碎后撒入）", "搅拌均匀，关火", "盛盘，可额外淋上少量淡奶油作为装饰"]' WHERE id=712;
