UPDATE recipes SET description='白糖炒出焦黄糖色，鸡块下锅上色，香叶干线椒炒香，土豆盖在表面炖', steps='["肉先剁好，块状，用清水+盐浸泡 5 分钟，去除血水，去腥，然后空干水", "葱蒜辣椒土豆等洗干净，土豆削皮", "葱白切长段，长度 4cm 一段，菜椒和线椒切块状", "土豆切成滚刀土豆，即切一刀动滚动一下，一块土豆大概有 4cm×4cm 大小即可", "炒糖色：先将油加入锅中，然后将白砂糖放入，用锅铲来回搅拌，将糖炒化，然后炒出焦黄色，此时将空干水的鸡肉倒入锅中翻炒，进行上色", "放入花椒，香叶，香果，干线椒等进行翻炒", "放入 5g 盐，生抽 7ml，蚝油 10g ，料酒 100g，倒入 1 升清水，料酒可以用啤酒代替", "调至中火，将水烧开，调制中小火慢炖入味", "当水收至鸡肉即将露出时，将土豆放在锅表面：注意不要翻动土豆，就盖在表面，不然翻到下面容易粘锅，继续盖锅盖炖，炖一会后将大葱，菜椒和甜椒放入，继续炖。", "炖到汁收的差不多时可以进行翻面，将土豆与汤汁相吸，最后关火盛出。"]' WHERE id=736;
UPDATE recipes SET description='鸡爪煮十分钟后进冰箱定型，再一个个拆骨，拌上小米辣蒜末柠檬汁' WHERE id=737;
UPDATE recipes SET description='牛腩焯水切大块，南乳豆瓣酱柱候酱依次炒香，沿锅边淋酒，再慢慢炖透', steps='["先把辅料备好：", "牛肉不用切，直接冷水下锅，开大火焯水，水沸腾时将牛肉捞出", "冲洗牛肉表面的杂质后，切成 4cm\\4cm\\4cm 的大块，控干水后放入碗中备用", "大火，热锅下油，把碗 1（姜、蒜、小米辣）倒入锅中，炒香", "中小火，倒入碗 2（香料），翻炒均匀，大概 30 秒", "中小火，放入碗 3（南乳），用锅铲把南乳压碎", "中小火，放入碗 4（豆瓣酱），翻炒均匀，大概 30 秒", "中小火，放入碗 5（冰糖），炒至融化", "中小火，下入牛腩，炒至牛肉上色", "大火，沿锅边淋入碗 6（酒），快速翻炒，炒至牛肉表面略微焦褐", "倒入碗 7（酱料），快速翻炒，留意底层汁水，炒至不停冒小气泡，汤汁略微浓稠", "将锅内全部食材转移至另一个炖煮锅或高压锅，加水淹过食材", "根据使用的锅来选择炖肉的时间：", "时间到后开盖调味，如果不够咸加盐或生抽（少量加，不断尝味道，直到合适），不够甜则同理加糖", "调好味道后便可以把牛腩先捞出", "如果要吃萝卜土豆，则削皮切成 2cm 厚片倒入锅中煮 10 - 15 分钟（或煮至想要吃的口感），如果是高压锅则在加压煮 5 分钟", "煮好后捞出萝卜土豆和牛腩放一起", "把汤汁过滤淋入碗中"]' WHERE id=739;
UPDATE recipes SET description='青椒、苦瓜、茄子、田螺都能酿，塞进猪肉馅或虾滑馅，煎过再焖' WHERE id=740;
UPDATE recipes SET description='牛肉片腌十五分钟，红汤里煮熟铺在豆芽上，最后热油泼辣椒粉和香菜' WHERE id=742;
UPDATE recipes SET steps='["五花肉切成厚度不超过 2cm 长的块，并串成串。（五花肉可以预先腌制一下，味道更佳）", "大葱切成 5cm 长的葱段，备用", "芝麻酱加 10ml 温水调稀，与甜面酱混合均匀，备用（可以换成"芝麻盐"）", "点燃炭火，等待炭火烧至通红无明火状态（约 15 分钟）", "将五花肉串均匀摆在在烤网上，烤至底面焦黄出油后翻面", "继续烤制约 2 - 3 分钟，至两面焦黄、边缘微焦后取下", "取一张小薄面饼平铺，抹上 3 - 4g 混合酱料", "放上烤好的肉片和 1 - 2 段大葱，卷起即可食用"]' WHERE id=743;
UPDATE recipes SET description='鳜鱼铺上姜片葱段大火蒸熟，撒红椒丝，淋生抽再泼一勺热油' WHERE id=744;
UPDATE recipes SET description='五花肉煮过去腥再切块，冰糖炒出焦糖色裹匀，加开水和香料小火炖半小时', steps='["带皮五花肉洗净冷水下锅，加入姜片 2~3 片去腥味，煮到沸腾捞出冷水冲净白沫", "五花肉切块，尺寸 1.5cm×1.5cm 块状大小", "热锅加入油，加入冰糖小火搅拌至焦糖色即可，加入切好的五花肉，中火翻炒上色", "加入备好的姜片、八角、桂皮、生抽、老抽、料酒、干小米椒、盐，小火翻炒 1 分钟，加开水没过肉", "加盖中火煮沸，转小火慢顿 30 分钟，慢炖期间，间隔 10 分钟搅拌一次防止粘锅", "小火慢炖汤汁剩三分之一的时，调成中火收汁出锅。"]' WHERE id=745;
UPDATE recipes SET description='鸭块煸到表皮焦香，关小火拌上米粉和辣椒粉，上高压锅蒸二十多分钟' WHERE id=746;
UPDATE recipes SET description='牛肉末用黄油和洋葱炒香，倒番茄酱汁收稠，盖在饭上再卧一个水波蛋' WHERE id=747;
UPDATE recipes SET steps='["将羊排按照骨头分布，切成块状。", "炒锅中加入冷水，放入全部羊排块，水沸腾后继续焯水 2 - 3 分钟，捞出备用。", "将焯好水的羊排、桂皮、花椒、八角、白芷、香叶、料酒放入锅中（高压锅或普通锅）。", "加入饮用水没过所有食材。如果使用高压锅，上汽后压 30 分钟。如果使用普通锅，炖煮 80 分钟。", "将炖煮完成的羊排捞出，沥干水分，放入无油无水的炒锅 / 煎锅中。", "中大火煎 6 - 7 分钟，直至羊排中的油脂被煎出，表面呈金黄酥脆状态。", "锅中保留煎出的羊油，加入辣椒粉、孜然粒、烧烤撒料、孜然粉、白芝麻，翻炒均匀。", "加入糖和盐（如果在炖煮步骤中未添加），翻炒均匀。", "翻炒均匀后即可关火，盛盘。"]' WHERE id=748;
UPDATE recipes SET description='牛排现磨海盐黑胡椒立刻下锅，单面煎一分半，最后放黄油和蒜瓣淋香' WHERE id=749;
UPDATE recipes SET description='猪皮焯水后把白肉剔干净，加香料小火煲一个半小时，晾凉就是水晶皮冻' WHERE id=750;
UPDATE recipes SET description='田螺肉剁碎和猪肉按比例拌馅，加薄荷紫苏去腥，再塞回螺壳里焖' WHERE id=751;
UPDATE recipes SET description='肉片用生粉生抽腌十分钟，土豆片先焯水，一起下锅炒三分钟' WHERE id=752;
UPDATE recipes SET description='猪蹄煮十五分钟去腥，冰糖熬糖色炒到微黄，转高压锅压一刻钟再收汁' WHERE id=755;
UPDATE recipes SET description='羊排炒出焦糖色，加水炖四十分钟，再把面皮铺进去一起焖熟' WHERE id=758;
UPDATE recipes SET description='猪蹄配当归白芷高压三十分钟，加泡好的白芸豆再压十分钟，汤色奶白才对' WHERE id=759;
UPDATE recipes SET description='罗氏虾先处理干净，蒜蓉和碗汁调好，下锅炒到裹匀，芥末的辛香直冲鼻子' WHERE id=761;
UPDATE recipes SET description='腊肠小火炒到微微卷边，再下焯过水的荷兰豆，大火翻炒一分钟', steps='["把荷兰豆去掉蒂，有时间的也可以同时把尾部去掉", "买腊肠之前可以问老板是生的还是熟的，如果是生的，需要提前蒸一下，如果是熟的可以直接使用", "把荷兰豆清洗一下，然后焯一下水，大概 45s，荷兰豆焯至变色即可，捞出过凉水备用", "热锅，锅内放入大约 10ml 食用油。等待 10 秒让油温升高", "放入腊肠，保持翻炒至腊肠微微卷边，注意这里一定要保持小火，小到不能小的那种，不然容易糊", "放入荷兰豆，转为中大火，翻炒 30s 放入生抽，接着再翻炒 20-30s 即可"]' WHERE id=764;
UPDATE recipes SET description='鸭块炒到泛白，加酒和开水焖二十五分钟，最后倒鲜鸭血让每块肉都裹上' WHERE id=765;
UPDATE recipes SET description='牛肉先焯水，和洋葱西红柿一起炒出汁，加香料慢炖到土豆绵软' WHERE id=766;
