UPDATE recipes SET description='白鱔切段铺盘，浇上剁碎的豆豉蒜蓉酱汁，上锅蒸熟再淋一勺热油' WHERE id=769;
UPDATE recipes SET description='鸡块和土豆条先各自炸过，糍粑辣椒炒出红油，倒啤酒焖足半小时' WHERE id=770;
UPDATE recipes SET description='牛腱子扎孔腌四五个小时，加黄豆酱和香料小火炖三个钟头，冷藏后再切片' WHERE id=772;
UPDATE recipes SET description='肉片炒到变色，下土豆片炒至边缘微黄，再加青椒大火煸出锅气，勾芡收汁', steps='["青椒去除根蒂切小块，土豆去皮切 2mm 薄片，猪肉切 4mm 薄片，葱横纵切 3mm 小段，姜蒜去皮拍散剁碎末；土豆淀粉加入约 15g 水搅拌均匀至水淀粉。", "起锅烧油，加热至 7 成热放入猪肉片，缓缓翻滚炒至去肉红色，加入约 3ml 酱油，翻炒肉片均匀上色，放入约 2g 盐。", "转 5 成油温，加入葱姜蒜炒 5 秒，然后加入土豆片，转 7 成油温均匀翻炒，加入约 5ml 酱油和 2g 盐，炒至土豆断生，表面轻微焦黄。", "转 8 成油温加入青椒，大火煸炒出锅气（有白烟冒出），反复均匀翻炒 1 分钟上色，最后在锅周围倒入水淀粉转 4 成火勾芡。", "在外观呈粘稠状态后关火，盛盘"]' WHERE id=774;
UPDATE recipes SET description='肉馅顺一个方向搅上劲，塞进青椒里，肉面朝下先煎，再淋酱汁焖入味' WHERE id=775;
UPDATE recipes SET description='花椒大蒜爆香，肉片炒变色后下香干和辣椒，最后放芹菜翻一分钟' WHERE id=776;
UPDATE recipes SET description='五花肉切薄片腌十分钟，单面煎到焦黄，蘸豆瓣酱用生菜卷着吃' WHERE id=777;
UPDATE recipes SET description='干香菇泡发，鸡腿肉煸至金黄，倒香菇水收浓汤汁，滑嫩又带菇香' WHERE id=778;
UPDATE recipes SET description='鸡爪先加八角香叶煮半小时，再用小米椒辣椒面炒的酱汁回锅翻炒收汁' WHERE id=779;
UPDATE recipes SET description='茄条先炸到边缘微黄，肉沫炒白，倒调好的鱼香汁爆炒收汁' WHERE id=780;
UPDATE recipes SET description='五花肉糜配花椒和咸鸭蛋炒香，豆腐下锅后从锅边倒开水，烧到入味', steps='["大蒜和生姜切碎，备用", "小米辣切成辣椒圈，备用", "五花肉切成肉糜（本来就是买的肉糜的跳过）", "肉糜中加入一半的食盐和味极鲜酱油，搅拌均匀，备用", "鸭蛋用菜刀竖着对半切开（注意安全），去除蛋黄（一定要去除，不然会腥），剩下的蛋白捣碎成大约 2 mm × 2 mm 大小，不用太碎，备用", "打开豆腐包装，用水果刀将在盒子中的豆腐划成大约 2.5 cm × 3 cm 大小，备用", "热锅，锅内放入 10ml - 15ml 食用油。等待 10 秒让油温升高", "调成小火，放入大蒜、生姜、辣椒圈、花椒、咸鸭蛋、蒜蓉辣酱翻炒 20 秒，炒出香味", "调成中火，放入肉糜，翻炒大约 1 分钟，肉炒变色", "调成小火，放入豆腐，将剩下的食盐、味极鲜酱油酱油均匀的洒在豆腐上", "从锅边倒入开水（不然豆腐容易破），没过豆腐即可", "开大火，水沸腾后立马转入中火，等待大约 10 分钟", "等到水只剩 1/5 并且豆腐表面已经入色，关火，盛盘"]' WHERE id=781;
UPDATE recipes SET description='牛柳腌过后大火炒到变色，下洋葱和菜椒，最后撒黑胡椒粉翻匀' WHERE id=782;
