UPDATE recipes SET description='鸡翅撒上罗勒碎，200 度烤十分钟，翻面再烤七分钟，皮就脆了' WHERE id=791;
UPDATE recipes SET description='汤圆放碗里加开水没过，微波炉高火四分钟，膨胀起来就熟了' WHERE id=792;
UPDATE recipes SET steps='["（可选）将 Mo ml 的油与洗净的米混合，尽量确保完全混合，即每粒米上至少都沾上少量油", "（可选）将 米-油混合物品冷藏保存，冷藏时间 Tc。", "将米和水加入锅中。", "开大火，加热到 T1。", "在 T1 之前将火关小。如果忘记此步骤，水可能会漫出而熄灭火焰。非常危险！", "加热到 Tr。在 Tr 时关闭火源。"]' WHERE id=798;
UPDATE recipes SET steps='["排骨洗净，切到约 4cm ±2cm × 3 ± 2cm 的小块（如没有剁排骨的工具，可以求助摊主）", "炒锅倒入冷水 700ml 和排骨一起加热至煮沸，关火捞出排骨", "苦瓜中间切为两半，清除干净内部的种子和苦瓜瓤，切为 0.5 ± 0.3 cm 的苦瓜条，洗净"]' WHERE id=808;
UPDATE recipes SET description='羊肉先焯水再下锅炒到微黄，冲入开水大火煮，出锅撒白胡椒、孜然和香菜' WHERE id=812;
UPDATE recipes SET description='银耳莲子泡两小时，中火熬一小时出胶，加冰糖枸杞再小火煨半小时' WHERE id=814;
UPDATE recipes SET steps='["在碗中混合烤鹰嘴豆粉 120g、切碎的洋葱、青辣椒、生姜", "加入孜然籽 3g、芝麻 5g、红辣椒粉 3g、印度黑盐 3g、盐 3g", "加入芥末油 15ml、柠檬汁 10ml、切碎的香菜叶", "充分混合均匀，馅料应呈松散但可捏合的状态，备用", "将全麦面粉 200g 放入大碗中", "逐渐加入温水，边加边揉，揉成光滑柔软的面团", "面团静置 15 分钟", "将面团分成 8 个等大的小剂子", "每个剂子用手压成一个直径约 8cm 的圆形面片（中间稍厚）", "在面片中央放入约 15g 馅料", "将面片四周收拢包住馅料，封口处捏紧，搓成圆球", "烤箱预热至 200°C", "将利提放在烤盘上，烤 25-30 分钟，期间翻面一次，直至表面金棕色且有裂纹", "如果使用明火：将利提直接放在炭火或煤气灶小火上烤，不断翻转，直至均匀焦黄", "烤好后趁热将每个利提表面涂上酥油，使其浸润吸收", "将茄子、番茄、土豆放在明火上直接烤，或放入 200°C 烤箱烤 20-25 分钟，直至外皮焦黑、内部完全软烂", "烤好后去皮，将茄子、番茄、土豆分别用叉子或手捣碎", "将捣碎的蔬菜混合在一起", "加入切碎的大蒜、青辣椒、盐 4g、芥末油 15ml", "充分搅拌混合均匀", "撒上香菜叶装饰", "将利提摆盘，旁边放上巧卡蔬菜泥", "趁热食用，用手掰开利提蘸巧卡"]' WHERE id=816;
UPDATE recipes SET steps='["将干酵母 3g 和糖 10g 溶解在 100ml 温水中（水温约 40°C，不可过烫）", "静置 5 分钟，直至表面冒出细泡沫（说明酵母已激活）", "在大碗中放入中筋面粉 300g 和盐 5g，混合均匀", "倒入酵母水、酸奶 60ml 和食用油 15ml", "用手揉成光滑柔软的面团（面团应比普通面团稍软，微微粘手是正常的）", "揉面 8-10 分钟", "在面团表面涂 3ml 油防止干裂", "用湿布或保鲜膜盖住碗口", "放置在温暖处发酵 至少 1 小时，直至面团膨胀至约两倍大", "将发酵好的面团取出，轻揉排气", "分成 6 个等大的小剂子（每个约 80g）", "取一个剂子，手上沾 3ml 面粉或油", "用擀面杖擀成长椭圆形或泪滴形面饼，厚度约 4-5mm", "如果制作蒜蓉烤饼：在面饼表面撒上切碎的大蒜和香菜叶，轻轻擀压使其嵌入面饼", "可在面饼表面撒上芝麻", "将平底锅（铸铁锅最佳）大火加热至非常烫（滴水立即蒸发的程度）", "在面饼一面刷一层薄薄的水", "将刷水一面朝下放入锅中", "烤 1-2 分钟，直至底面出现金棕色斑点且面饼开始鼓泡", "翻面，继续烤 1-2 分钟", "如果有煤气灶：翻面后可用夹子夹起面饼，将其直接放在明火上烤 数秒钟，面饼会迅速鼓起", "取出后立即在表面涂上酥油或黄油", "烤箱预热至最高温度（通常 250°C）", "将面饼放在烤盘上", "烤 3-5 分钟，直至表面金黄且鼓起", "取出后涂上酥油或黄油", "趁热食用", "适合搭配任何印度咖喱，如黄油鸡、红芸豆咖喱等"]' WHERE id=817;
UPDATE recipes SET steps='["在大碗中混合酸奶、磨碎的生姜和大蒜、红辣椒粉、姜黄粉、印度综合香料粉、盐、柠檬汁", "放入鸡肉块，均匀裹上腌料", "盖保鲜膜，冷藏腌制至少 1 小时（过夜更佳）", "将藏红花 0.5g 放入 30ml 温牛奶中浸泡 15 分钟，备用", "在锅中倒入 50ml 食用油，中火加热", "放入洋葱薄片，翻炒至深金棕色且酥脆（约 12-15 分钟，需耐心）", "捞出炸洋葱，用厨房纸吸油，备用", "将浸泡好的巴斯马蒂香米沥干", "在大锅中烧开 2000ml 水", "加入月桂叶、小豆蔻、丁香、肉桂棒、八角和盐 10g", "放入米饭，大火煮 5-6 分钟，直至米粒约七成熟（外部软、芯部仍有硬度）", "立即沥干，丢弃全香料，备用", "在厚底锅底部涂抹酥油 15g", "第一层：将腌制好的鸡肉均匀铺在锅底", "第二层：铺上一半的半熟米饭", "撒上一半的炸洋葱、薄荷叶、香菜叶、青辣椒", "第三层：铺上剩余的米饭", "撒上剩余的炸洋葱、薄荷叶、香菜叶", "将藏红花牛奶均匀淋在最上层米饭表面", "放上剩余的酥油 15g（切小块散放）", "密封锅盖：用面粉加水和成面团条，沿锅口边缘封住缝隙（传统方法），或用锡纸包裹锅口再盖锅盖", "先用大火加热 3 分钟，直至锅内开始冒蒸汽", "然后转最小火，焖 25-30 分钟", "关火后不要开盖，再焖 5 分钟", "开盖，用大铲子从底部轻轻翻拌，使各层混合均匀", "盛盘，搭配酸奶(Raita)食用"]' WHERE id=818;
UPDATE recipes SET steps='["菜码切丝备用。", "葱切碎。油锅烧热，下葱和肉，炒至肉完全熟透（无红色）", "下豆瓣酱和甜面酱，继续炒至微微粘稠。盛出，得到炸酱。", "取大碗，加凉水备用。", "煮面条至断生（无白芯），盛入第 4 步装有凉水的碗中。", "立即控水捞出，盛入干净的碗中。", "取第 3 步炸酱，倒入碗中，拌匀。然后取第 1 步菜码，倒入碗中，拌匀。"]' WHERE id=827;
UPDATE recipes SET steps='["将干红芸豆用清水浸泡至少 8 小时（过夜），浸泡后体积会膨胀约两倍", "将浸泡好的红芸豆沥干", "使用高压锅：放入红芸豆和 600ml 水，盖好锅盖，大火上气后转中火，压 15-20 分钟，直至豆子用手指可轻松压碎", "使用普通锅：放入红芸豆和足量水，大火煮沸后转中火，煮 60-90 分钟，直至豆子完全软烂", "煮好后保留煮豆汤水，备用", "在炒锅中倒入 30ml 食用油，中火加热", "放入月桂叶 2 片，炸至散出香味（约 10 秒）", "放入切碎的洋葱，翻炒至金棕色（约 6-8 分钟）", "加入磨碎的生姜和大蒜，翻炒 1 分钟", "加入切碎的番茄，翻炒至番茄完全软烂出油（约 5 分钟）", "加入姜黄粉 3g、红辣椒粉 5g、香菜粉 5g、孜然粉 3g、盐 6g", "翻炒 2 分钟，使香料与番茄融合", "将煮好的红芸豆连同汤水一起倒入锅中", "加入青辣椒，搅拌均匀", "大火煮沸后转小火，炖 15-20 分钟", "期间用铲子背面压碎一部分豆子，使汤汁变得浓稠", "加入印度综合香料粉 3g，搅拌均匀", "关火，撒上香菜叶", "将大米淘洗干净", "放入电饭锅，加入 400ml 水", "正常蒸煮即可", "将米饭盛入盘中", "将红芸豆咖喱浇在米饭上或旁边", "可搭配洋葱沙拉和柠檬角"]' WHERE id=832;
UPDATE recipes SET steps='["猪肉去皮，切成 2 cm × 6 cm × 0.5 cm 薄片备用", "芹菜去叶，去掉根部 2cm，然后从中对半切开，切成 2cm 段备用", "大蒜去皮切粒备用，葱切 0.2cm 薄片备用，姜切细丝备用", "炒锅烧热至冒烟后，倒入 3ml 食用油滑锅后倒出底油", "重新加入食用油，加入肉片，葱姜蒜，干红椒，炒 1 分钟，注意不停匀速翻炒", "加入料酒，生抽，老抽，再翻炒 1 分钟", "续入 500ml 热水。盖上锅盖炖煮 3 分钟", "将芹菜，青椒倒入锅中，加入盐，五香粉调味，盖上锅盖继续炖煮 3 分钟 后关火", "蒸锅加入 1000ml 水，烧开上汽后，将面条摊平在笼屉上放入锅中，蒸 15 分钟", "面条蒸熟后取出，用筷子和无情铁手扒拉散开在案板上，室温冷却", "将面条放入菜锅中搅拌，搅拌方式为一手持筷，一手持锅铲将菜翻至面条上面，以面条以全部均匀上色为搅拌完成标准", "将搅拌后的面条再次放在整屉上，再次蒸 10 分钟 关火"]' WHERE id=836;
UPDATE recipes SET steps='["将干鹰嘴豆用清水浸泡过夜（至少 8 小时），浸泡后体积会膨胀至约两倍", "将浸泡好的鹰嘴豆沥干水分", "放入锅中，加入 500ml 水和 1 个红茶包（用于上色）", "大火煮沸后转中火，煮 25-30 分钟，直至鹰嘴豆用手指可以轻松压碎", "取出红茶包，保留煮豆的汤水，备用", "在炒锅中倒入 30ml 食用油，中火加热", "放入切碎的洋葱，翻炒至金棕色（约 6-8 分钟）", "加入磨碎的生姜和大蒜，翻炒 1 分钟", "加入切碎的番茄，翻炒至番茄完全软烂出油（约 5 分钟）", "加入姜黄粉 3g、红辣椒粉 5g、香菜粉 8g、孜然粉 5g、盐 6g", "翻炒 2 分钟，使香料充分释放香味", "将煮好的鹰嘴豆连同汤水一起倒入锅中", "加入青辣椒，搅拌均匀", "大火煮沸后转小火，炖 15-20 分钟，期间可用铲子背面压碎一些鹰嘴豆使汤汁变稠", "加入印度综合香料粉 5g 和石榴粉 3g（或柠檬汁 15ml）", "搅拌均匀后关火，备用", "在大碗中混合中筋面粉 250g、小苏打 2g、盐 3g", "加入酸奶 60ml 和食用油 15ml", "逐渐加入温水，边加边揉，揉成光滑柔软的面团（面团应比普通面团稍软）", "用湿布盖住面团，静置 30 分钟", "将面团分成 8 个等大的小剂子", "取一个剂子，手上沾少量油，擀成直径约 15cm、厚度约 3mm 的圆形面饼", "在深锅中倒入 500ml 食用油，中大火加热至油温约 180°C", "将面饼轻轻滑入热油中，用漏勺轻轻按压面饼使其膨胀鼓起", "炸 1-2 分钟，翻面炸至两面金黄", "捞出，用厨房纸吸去多余油分", "将鹰嘴豆咖喱重新加热", "炸饼趁热上桌，搭配鹰嘴豆咖喱食用", "可搭配切片洋葱、青辣椒和柠檬角"]' WHERE id=844;
UPDATE recipes SET description='豌豆淀粉糊煮到浓稠冷藏定型，切条后浇上蒜末辣椒油和花生碎' WHERE id=848;
UPDATE recipes SET description='先用酵母和温水做酵头，起泡后再揉进面团，两次发酵烤出松软面包', steps='["首先，将酵母和 30℃ 的温水 用刮刀或厨具混合均匀，静置 5 分钟。之后与面粉混合，搅拌均匀。此时的酵头应该是特别粘稠的面糊。", "用布盖上面糊，将面糊放置到温暖的地方进行发酵，时长为 45 ~ 60 分钟。", "最终的面糊应该是表面有很多气泡的且体积明显增大。", "将剩下的原料全部与酵头用刮刀混合、搅拌。在搅拌时一定要刮壁，使其充分混合。在形成面团且没有干粉时，用干净的干燥的一只手按压面团，另一只手扶住容器，使其形成一个大的面团，然后倒在面板或硅胶垫上操作", "用手掌下部推开面团，然后对折再次推开，直至表面没有干粉结块。这时的面团还不是很光滑。", "使用喷壶将至少是当前面团三倍大的容器内喷上一层植物油（也可用手涂抹均匀），将面团放入并盖上布，发酵 1 小时。", "此时面团应该有原来的两倍大。在面板或硅胶垫上撒上薄薄的一层面粉（可以看见面板或硅胶垫的厚度即可），然后将面团拿出，用手压瘪面团排气。", "之后使用擀面杖，擀成 1 cm 的厚片。并紧实、不留空隙地从一边卷起来。", "然后旋转 90° ，重复步骤 4、步骤 5 。", "将面包整形，放到垫了硅油纸的烤盘或者涂抹油脂的模具内。注意接缝处朝下。", "在托盘或模具内，发酵 30 ~ 45 分钟 。", "于此同时，预热烤箱。", "在面包上用剪子或者刀划开几条缝作为面包的花纹。", "用刷子刷上蛋液。（可选）", "放入烤箱，上下火 180℃ 烤制 30 分钟，然后调 165 ℃ 再烤 10 分钟。", "放凉后装入食品袋内，可保存一个星期。冷冻可保存一个月。"]' WHERE id=849;
UPDATE recipes SET description='米加水先高火六分钟，铺上腊肠再两分钟，青菜鸡蛋摆好淋生抽撒葱花' WHERE id=850;
UPDATE recipes SET description='洋葱碎炒到半透明，下肉沫炒成棕色，加意面酱炒匀后拌面' WHERE id=851;
UPDATE recipes SET steps='["胡萝卜切丁 0.2cm×0.2cm×0.2cm，备用", "午餐肉切丁 0.2cm×0.2cm×0.2cm，备用", "葱分别取葱白和葱绿，各切成 0.25-0.5cm 的小段，分开备用", "在碗中打入鸡蛋液，均匀搅拌，备用", "将胡萝卜，青豆，玉米粒煮熟捞出，备用（水别倒）", "将虾煮熟，捞出备用（水可以倒了）", "热锅热油，可以参考[学习炒与煎](../../../tips/learn/学习炒与煎.md)中的热锅双油", "鸡蛋凝固后立刻捞出，备用", "将午餐肉，青豆，胡萝卜，玉米粒，虾倒入锅中翻炒 1-2 分钟，装盘备用", "水冲一下锅，将杂物冲干净，保证锅内干净（可以有油但是不能有杂质）", "热锅热油(10ml)，将葱白放入爆香", "调至小火（如果油温过高可以关火 1-2 分钟），放入米饭，用铲子快速砸击米饭并翻炒，保证米饭均匀沾到油且粒粒分明", "倒入鸡蛋，继续砸击，使鸡蛋碎开并与米饭充分混合", "转大火，倒入其他所有备用配料，快速翻炒 1-2 分钟", "撒入盐，并翻炒至充分混合", "撒入葱绿，翻炒 1 分钟", "关火，装盘"]' WHERE id=852;
UPDATE recipes SET description='面团和好放冰箱冷藏一晚上，第二天分成四份擀开，铺料撒芝士烤' WHERE id=853;
UPDATE recipes SET steps='["胡萝卜去头尾，去皮，滚刀切", "洋葱剥去外层去芯，切成月牙状", "土豆去皮、切大块", "肉切块状", "剥蒜拍平切碎", "咖喱块切碎，增加接触面积加速溶解", "热油锅放入蒜和肉，快速翻炒至肉表面变白", "加入胡萝卜，快速翻炒至均匀受热", "加入洋葱，快速翻炒至洋葱变透明状", "加入土豆，保持翻炒至土豆变软（可以用筷子确认）", "加水没过所有食材，沸腾后等待 15 分钟", "关火，加咖喱并搅拌", "等待咖喱融化后再开火，缓慢搅拌 10 分钟，防止糊锅", "在外观呈粘稠状态关火结束制作", "微波炉：单人份高火 2-3 分钟", "锅：需额外加 50ml 水，加热时保持搅拌"]' WHERE id=854;
UPDATE recipes SET steps='["洋葱剥去外层去芯，切成月牙状", "葱洗净切成 0.5cm 的小段", "热锅直接放入白芝麻，前后晃动锅体使芝麻均匀受热至略呈金黄色", "肥牛焯水 1 分钟后捞出", "将 40g 味淋（或 30g 料酒），30g 酱油，20g 耗油，5g 糖，5g 老抽（可选，用于调色），在碗中搅拌混合成调料（该步骤可直接将碗放在电子秤上进行）", "热油锅放入洋葱，快速翻炒至洋葱变透明状", "关小火，加入 250g 水（或出汁），开回大火加热等待 3 分钟", "加入牛肉和调料", "不断翻动所有食材 10 分钟，防止食材粘锅", "关火", "盛装肥牛丼至[米饭](../米饭/电饭煲蒸米饭.md)上（注意要把汁水淋一些在饭上）", "撒上葱花和白芝麻，制作完成。", "微波炉：单人份高火 2-3 分钟", "锅：需额外加 50ml 水，加热时需不断翻动"]' WHERE id=855;
UPDATE recipes SET description='挂面先蒸十五分钟，五花肉和蒜薹炒出汤，把面拌进去吸透汤汁' WHERE id=856;
UPDATE recipes SET description='米饭拌上火腿丁、青豆玉米和海苔碎，加沙拉酱捏成饭团' WHERE id=857;
UPDATE recipes SET description='凉粉切麻将块，豆瓣酱炒出红油后下锅，加辣椒面翻炒，收稠汤汁撒葱花' WHERE id=858;
