UPDATE recipes SET description='鸡肉加蛋和压碎的饼干拌成肉饼，淋照烧料汁，空气炸锅烤四十分钟', steps='["将酱油、糖和醋混合在一起,搅匀料汁备用", "另一个碗中加入鸡肉、鸡蛋、1/2 料汁和压碎的丽滋饼干。搅拌均匀", "空气炸锅用箔纸碗铺底，加入肉饼混合物，将剩余的料汁均匀的倒在上面", "350°F(177°C) 炸40 分钟。最好在米饭上食用", "在外观呈金黄酥脆后出锅，切块盛盘"]' WHERE id=864;
UPDATE recipes SET description='酸笋先不下油炒干水汽，再下油和蒜蓉剁椒豆豉炒香，加汤煮开后下米粉' WHERE id=867;
