UPDATE recipes SET description='蔬菜切丝炒软，牛肉卷焯熟，围着米饭摆一圈，中间卧个溏心蛋，淋辣酱' WHERE id=873;
UPDATE recipes SET description='热米饭拌上玉米粒和鲣鱼海苔碎，拌匀就能吃，最快的一碗饭' WHERE id=874;
UPDATE recipes SET steps='["葱切花，蒜切沫，备用。", "生抽、老抽、耗油、盐混合调料汁，备用。", "小米椒切圈，备用。", "豆角去筋，45° 斜切4-10cm小段，备用。", "起锅烧油(10ml - 15ml)，冒烟后放入葱、小米椒，翻炒至闻到香味；", "加入豆角，翻炒30s,", "加入料汁，开大火翻炒2分钟", "倒入 150ml 水", "转中小火，盖上锅盖焖制 8-10 分钟", "加入蒜切沫，出锅。"]' WHERE id=890;
UPDATE recipes SET steps='["葱切花，蒜切沫，姜切丝，备用。", "豆角去筋，切2-10cm小段，备用。", "土豆去皮，切1cm³小块，备用。", "西红柿去皮，切1cm³小块，备用。", "辣椒去仔，切0.15cm 宽条，备用。", "起锅烧油(10ml - 15ml)，冒烟后放入葱姜蒜，翻炒至闻到葱姜蒜香味；", "加入豆角，翻炒至变色（青绿色变为翠绿色）；", "加入土豆块，翻炒 30s；", "加入热水（水面刚刚漫过菜），盖上锅盖熬至土豆变软（可以用筷子确认）；", "加入西红柿块，加入盐，生抽，蚝油，五香粉，辣椒，熬至西红柿成汁（注意搅拌，防止糊锅）；", "加入香菜碎，出锅。"]' WHERE id=902;
UPDATE recipes SET steps='["娃娃菜洗净, 竖着切开切成段。", "葱 3g 切 小段。蒜 10g 切片。姜 10g 切小片。", "皮蛋切成丁, 火腿肠或者午餐肉切成丁（1cm 大小的丁）", "金针菇洗净撕开", "烧热水娃娃菜放进去十秒钟出一下水捞出。", "热锅凉油, 加热锅倒入油过一遍就倒出来, 重新倒入一点油。", "调至小火加入葱姜蒜，煎炒出香味即可。", "加入适 300g 清水（水量没过娃娃菜即可）, 放入娃娃菜, 金针菇, 午餐肉", "加入调味料蚝油、糖、盐、味精烧开。", "煮 3 分钟, 煮开后开始装盘, 盛出娃娃菜后皮蛋放在上面把汤汁浇上去就可以了"]' WHERE id=905;
UPDATE recipes SET steps='["大白菜只取内部嫩叶（黄色部分），去除菜帮，用手撕成半个巴掌大的块，不要用刀切（手撕截面粗糙更易挂酱）", "将撕好的白菜叶冲洗干净，充分控干水分，水分残留会导致酱汁无法挂附", "碗中加入 30g 芝麻酱，先加入 45ml 陈醋，沿同一方向搅拌，将麻酱慢慢稀释开，直至成细线状滴落为止（切勿来回搅拌，会导致芝麻酱"走油"）", "向麻酱汁中加入 5g 白糖，搅拌均匀；再加入 1g 食盐，搅拌均匀；最后加入 5ml 香油，搅拌均匀（各调料需分次加入并分别搅拌，边加边感受稀稠度）", "将调好的麻酱汁均匀淋在白菜叶上，用手轻轻抓拌，使每片菜叶都裹上酱汁", "撒上熟白芝麻，装盘即可食用；若时间充裕，可静置 5 分钟待其入味后再食用"]' WHERE id=906;
