UPDATE recipes SET description='藕丁先焯两分钟保持脆感，葱和小米辣爆香后大火翻炒两分钟' WHERE id=911;
UPDATE recipes SET description='花菜焯一分钟立刻过凉水，五花肉煸出油，和辣椒一起大火翻炒' WHERE id=912;
